                throw ServerException("Server error : ${localVarError.statusCode} ${localVarError.message.orEmpty()} ${localVarError.body}", localVarError.statusCode, localVarResponse)
            }
        }
    }

    /**
     * PUT /api/files/{id}/progress
     * Report the playback position of a file
     * Stores the position against the movie or episode(s) the file belongs to. Past the start of the final credits, or 92% of the duration without them, the item is marked watched. A trailer&#39;s reports are taken and not stored: it has no watch state.
     * @param id Media file ID.
     * @param progressInputBody 
